// Generated by sel-pull (Shared Element Library): do not edit, it is replaced by the next "sel-pull firebase". The project's own part is
// scripts/dev-seed.mjs.
//
// Shared by the local dev scripts (npm run dev / dev:seed / dev:pull / dev:load): the emulator hosts from firebase.json, wiping and
// filling the local database and Auth accounts, and the JSON format a live copy is saved in.
//
// Importing this module points this process's firebase-admin at the EMULATORS (the env variables below are what firebase-admin reads),
// so everything written from here lands on this machine. pull-live.mjs, which reads the live project, never imports it.
import fs from "node:fs";
import http from "node:http";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const readJson = (file) => JSON.parse(fs.readFileSync(path.join(ROOT, file), "utf8"));
export const PROJECT_ID = readJson(".firebaserc").projects.default;
const emulators = readJson("firebase.json").emulators || {};
const hostOf = (name) => (emulators[name] ? `${emulators[name].host || "127.0.0.1"}:${emulators[name].port}` : null);
export const FIRESTORE_HOST = hostOf("firestore");
export const AUTH_HOST = hostOf("auth");
export const HOSTING_URL = emulators.hosting ? `http://localhost:${emulators.hosting.port}` : null;
export const UI_URL = emulators.ui?.enabled !== false && emulators.ui?.port ? `http://localhost:${emulators.ui.port}` : null;
export const DATA_DIR = path.join(ROOT, ".emulator");
export const SEED_FILE = path.join(ROOT, "scripts", "dev-seed.mjs");
export const PENDING_COPY = path.join(DATA_DIR, "load-on-start"); // left by a pull while the emulators were down

if (!FIRESTORE_HOST) {
  console.error('firebase.json has no "emulators.firestore" block. Add it with: node scripts/sel-pull.mjs firebase');
  process.exit(1);
}

process.env.FIRESTORE_EMULATOR_HOST = FIRESTORE_HOST;
if (AUTH_HOST) process.env.FIREBASE_AUTH_EMULATOR_HOST = AUTH_HOST;
process.env.GCLOUD_PROJECT = PROJECT_ID;
process.env.GOOGLE_CLOUD_PROJECT = PROJECT_ID; // known up front, so firebase-admin never goes looking for it on the network
process.env.METADATA_SERVER_DETECTION = "none"; // not on a Google Cloud machine: skip pinging its metadata server (slow, and a warning)

const { initializeApp } = await import("firebase-admin/app");
const { getFirestore, Timestamp, GeoPoint, FieldValue } = await import("firebase-admin/firestore");
const { getAuth } = await import("firebase-admin/auth");

const app = initializeApp({ projectId: PROJECT_ID }, "emulator");
export const db = getFirestore(app);
export const auth = AUTH_HOST ? getAuth(app) : null;
export { Timestamp, GeoPoint };

const OWNER = { Authorization: "Bearer owner" }; // the emulators' admin token: bypasses the rules, emulator only
// A one-off connection (no keep-alive): fetch would leave pooled sockets closing, and exiting then crashes Node on Windows.
const reachable = (url) => new Promise((resolve) => {
  http.get(url, { agent: false }, (res) => { res.resume(); resolve(true); }).on("error", () => resolve(false));
});

/** Every configured emulator that serves something answers (they come up one after the other). */
export async function emulatorsRunning() {
  const urls = [`http://${FIRESTORE_HOST}/`, AUTH_HOST && `http://${AUTH_HOST}/`, HOSTING_URL].filter(Boolean);
  return (await Promise.all(urls.map(reachable))).every(Boolean);
}

export async function requireEmulators() {
  if (!(await emulatorsRunning())) {
    console.error("The emulators aren't running. Start them first: npm run dev");
    process.exit(1);
  }
}

const post = (url, body) => new Promise((resolve, reject) => {
  const req = http.request(url, { method: "POST", agent: false, headers: { ...OWNER, "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) } }, (res) => {
    const chunks = [];
    res.on("data", (c) => chunks.push(c));
    res.on("end", () => resolve({ status: res.statusCode, text: Buffer.concat(chunks).toString("utf8") }));
    res.on("error", reject);
  });
  req.setTimeout(10000, () => req.destroy(new Error("no answer within 10 seconds")));
  req.on("error", reject);
  req.end(body);
});

/**
 * Whether the local database has no documents at all. True ONLY for a verified answer: HTTP 200 whose JSON says there are no
 * collections. Anything else (an error status, a body that is not JSON, a connection error) throws: "could not check" must never be read
 * as "empty", because empty means "fill it with the demo data" (which wipes).
 */
export async function isEmpty() {
  const { status, text } = await post(`http://${FIRESTORE_HOST}/v1/projects/${PROJECT_ID}/databases/(default)/documents:listCollectionIds`, "{}");
  if (status !== 200) throw new Error(`the Firestore emulator answered ${status}`);
  let body;
  try {
    body = JSON.parse(text);
  } catch {
    throw new Error("the Firestore emulator's answer is not JSON");
  }
  if (!body || typeof body !== "object" || Array.isArray(body)) throw new Error("the Firestore emulator's answer is not an object");
  if (body.collectionIds === undefined) {
    if (Object.keys(body).length) throw new Error("the Firestore emulator's answer is not the list of collections");
    return true; // a 200 with {} is how the emulator says "no collections"
  }
  if (!Array.isArray(body.collectionIds)) throw new Error("the Firestore emulator's list of collections is not a list");
  return body.collectionIds.length === 0;
}

// ---- Checks that run BEFORE anything is wiped (load.mjs and seed.mjs): bad input must leave the local data untouched ----

const isPlainObject = (v) => !!v && typeof v === "object" && !Array.isArray(v) && [Object.prototype, null].includes(Object.getPrototypeOf(v));

/** Throws unless docs is a list of { path, data } with a document path (an even number of non-empty segments), plain data, no duplicates. */
export function validateDocs(docs) {
  if (!Array.isArray(docs)) throw new Error("the documents are not a list");
  const seen = new Set();
  Array.from(docs).forEach((d, i) => {
    const where = `document ${i + 1}`;
    if (!d || typeof d !== "object") throw new Error(`${where} is not { path, data }`);
    if (typeof d.path !== "string" || !d.path) throw new Error(`${where} has no path`);
    const segments = d.path.split("/");
    if (segments.some((s) => !s)) throw new Error(`${where}: the path "${d.path}" has an empty part (a leading, trailing or double slash)`);
    if (segments.some((s) => s === "." || s === ".." || /^__.*__$/.test(s) || Buffer.byteLength(s) > 1500)) throw new Error(`${where}: the path has an invalid or oversized segment`);
    if (segments.length % 2) throw new Error(`${where}: the path "${d.path}" is a collection, not a document (a document path has an even number of parts, like items/first)`);
    if (!isPlainObject(d.data)) throw new Error(`${where} (${d.path}): data must be an object`);
    validateValue(d.data, new Set(), false);
    if (seen.has(d.path)) throw new Error(`${where}: the path "${d.path}" occurs twice`);
    seen.add(d.path);
  });
}

// Catch serialisation errors before DELETE, including undefined, cycles and unsupported class instances in a project's seed module.
// Not stricter than Firestore itself: a FieldValue (serverTimestamp, increment, ...) and a vector are real values a seed may use.
function validateValue(value, parents, inArray) {
  if (value === null || ["string", "boolean", "number"].includes(typeof value)) return;
  if (!value || typeof value !== "object") throw new Error("document data contains an unsupported value");
  if (value instanceof Timestamp || value instanceof GeoPoint || Buffer.isBuffer(value) || value instanceof Uint8Array) return;
  if (FieldValue && value instanceof FieldValue) return;
  if (value.constructor && value.constructor.name === "VectorValue") return;
  if (value instanceof Date) { if (!Number.isFinite(value.getTime())) throw new Error("document data contains an invalid date"); return; }
  if (typeof value.path === "string" && typeof value.listCollections === "function") return;
  if (parents.has(value)) throw new Error("document data contains a cycle");
  const array = Array.isArray(value);
  if (array && inArray) throw new Error("Firestore does not support directly nested arrays");
  if (!array && !isPlainObject(value)) throw new Error("document data contains an unsupported object");
  parents.add(value);
  for (const v of array ? value : Object.values(value)) validateValue(v, parents, array);
  parents.delete(value);
}

/**
 * Checks the accounts: missing/null, or a list of { email, ... } (uid, when given, is a text). Returns { people, warnings }: people is the
 * list to create (every one with an explicit uid), or null when there is none.
 *
 * Wrong TYPES and a missing email always throw (a damaged or hand-made file). A VALUE the emulator cannot take is an error in a seed (the
 * developer wrote it) but, with { live: true }, a copy of production data: production may legitimately hold it (several accounts with one
 * email, a photo that is not http, a very long uid), and a copy must not become unloadable because of one account. Then the account (or
 * only the offending field) is left out and a warning says which, instead of refusing before the wipe.
 */
export function validatePeople(people, { live = false } = {}) {
  const warnings = [];
  if (people === undefined || people === null) return { people: null, warnings };
  if (!Array.isArray(people)) throw new Error("the people (accounts) are not a list");
  const emails = new Set();
  const uids = new Set();
  const out = [];
  const problem = (i, p, text, fix) => {
    if (!live) throw new Error(`person ${i + 1}${p && p.email ? ` (${p.email})` : ""}: ${text}`);
    warnings.push(`account ${p && p.email ? p.email : i + 1}: ${text}; ${fix}`);
  };
  Array.from(people).forEach((original, i) => {
    if (!original || typeof original !== "object" || Array.isArray(original)) throw new Error(`person ${i + 1} is not an object`);
    const p = { ...original };
    if (typeof p.email !== "string" || !p.email) throw new Error(`person ${i + 1} has no email address`);
    if (p.uid !== undefined && (typeof p.uid !== "string" || !p.uid)) throw new Error(`person ${i + 1} (${p.email}): uid must be a text`);
    for (const key of ["emailVerified", "disabled"]) if (p[key] !== undefined && typeof p[key] !== "boolean") throw new Error(`person ${i + 1}: ${key} must be a boolean`);
    for (const key of ["displayName", "photoURL", "provider", "providerUid", "phoneNumber"]) if (p[key] != null && typeof p[key] !== "string") throw new Error(`person ${i + 1}: ${key} must be text`);
    if (p.customClaims != null && !isPlainObject(p.customClaims)) throw new Error(`person ${i + 1}: custom claims must be an object`);
    p.uid = p.uid || `local-${i + 1}`;
    if (!/^[^\s@/]+@[^\s@/]+\.[^\s@/]+$/.test(p.email) || p.email.length > 254) return problem(i, p, "invalid email address", "left out");
    if (p.uid.length > 128) return problem(i, p, "uid longer than 128 characters", "left out");
    if (uids.has(p.uid) || emails.has(p.email.toLowerCase())) return problem(i, p, "duplicate email/uid", "left out (the first one is kept)");
    if (p.phoneNumber && !/^\+[1-9]\d{1,14}$/.test(p.phoneNumber)) { problem(i, p, "invalid phone number", "the phone number is left out"); delete p.phoneNumber; }
    if (p.photoURL) {
      let ok = false;
      try { ok = ["http:", "https:"].includes(new URL(p.photoURL).protocol); } catch { /* not a URL */ }
      if (!ok) { problem(i, p, "invalid photo URL", "the photo is left out"); delete p.photoURL; }
    }
    if (p.customClaims != null && Buffer.byteLength(JSON.stringify(p.customClaims)) > 1000) { problem(i, p, "custom claims exceed 1000 bytes", "the claims are left out"); delete p.customClaims; }
    emails.add(p.email.toLowerCase());
    uids.add(p.uid);
    out.push(p);
  });
  return { people: out, warnings };
}

/** Command line of a dev script: { flags: Set, positional: [...] }; an unknown option stops the script before anything is touched. */
export function parseArgs(argv, known, maxPositional) {
  const flags = new Set();
  const positional = [];
  for (const arg of argv) {
    if (arg.startsWith("--")) {
      if (!known.includes(arg)) { console.error(`Unknown option ${JSON.stringify(arg)}. Nothing was changed. Supported: ${known.join(", ") || "none"}`); process.exit(1); }
      flags.add(arg);
    } else positional.push(arg);
  }
  if (positional.length > maxPositional) { console.error(`Unexpected argument ${JSON.stringify(positional[maxPositional])}. Nothing was changed.`); process.exit(1); }
  return { flags, positional };
}

/** Empties the local database and removes every local Auth account. */
export async function wipe() {
  const calls = [fetch(`http://${FIRESTORE_HOST}/emulator/v1/projects/${PROJECT_ID}/databases/(default)/documents`, { method: "DELETE", headers: OWNER })];
  if (AUTH_HOST) calls.push(fetch(`http://${AUTH_HOST}/emulator/v1/projects/${PROJECT_ID}/accounts`, { method: "DELETE", headers: OWNER }));
  const results = await Promise.all(calls);
  if (results.some((r) => !r.ok)) throw new Error(`Wiping the emulators failed (${results.map((r) => r.status).join(" / ")})`);
}

// ---- Replacing the local data safely (load.mjs and seed.mjs): one at a time, with a safety copy of what is there ----
//
// 1. A lock file (.emulator/replace.lock) lets only ONE replacement run: a second load/seed is refused with a clear message. A lock of a
//    process that is gone (or from before the last reboot) is taken over.
// 2. When the emulators hold data, all of it (every document, the accounts with an email address) is first saved to
//    .emulator/backup-before-<load|seed>-<time>.json, written atomically, in the live-copy format, so npm run dev:load -- <that file> puts it
//    back. If the copy cannot be made (disk full...), nothing is wiped. --no-backup skips it.
// 3. Only then: wipe, write. A failure (or Ctrl+C) from there on prints where the copy is and the command to restore it, and keeps the copy
//    for good (renamed to .failed.json). After a success only the newest copy of that kind is kept.
const LOCK_FILE = path.join(DATA_DIR, "replace.lock");
const rel = (file) => path.relative(ROOT, file).split(path.sep).join("/"); // forward slashes: they survive every shell
const run = { kind: null, phase: "idle", backup: null }; // what this process is doing, for the exit handler

const pidAlive = (pid) => {
  try { process.kill(pid, 0); return true; } catch (err) { return err.code === "EPERM"; }
};
const readLock = () => {
  try {
    const held = JSON.parse(fs.readFileSync(LOCK_FILE, "utf8"));
    return held && Number.isInteger(held.pid) ? held : { damaged: true };
  } catch (err) {
    return err.code === "ENOENT" ? null : { damaged: true };
  }
};
const staleLock = (held) => held.damaged || !pidAlive(held.pid) || (Number.isFinite(held.at) && held.at < Date.now() - os.uptime() * 1000 - 5000); // before the last boot: the pid may be anyone's now

/** Keeps a safety copy for good (a later successful run must not prune it): renamed to .failed.json. Returns the file's final name. */
function keepBackup(file) {
  const kept = file.replace(/\.json$/, ".failed.json");
  try { fs.renameSync(file, kept); return kept; } catch { return file; }
}

function writeLock(extra) {
  const text = JSON.stringify({ pid: process.pid, kind: run.kind, at: Date.now(), ...extra });
  const tmp = `${LOCK_FILE}.${process.pid}.tmp`;
  fs.writeFileSync(tmp, text);
  return tmp;
}

function releaseLock() {
  const held = readLock();
  if (held && held.pid === process.pid) fs.rmSync(LOCK_FILE, { force: true });
}

function acquireLock(kind) {
  run.kind = kind;
  fs.mkdirSync(DATA_DIR, { recursive: true });
  const tmp = writeLock({ phase: "starting", backup: null });
  try {
    for (let attempt = 0; attempt < 4; attempt++) {
      try {
        fs.linkSync(tmp, LOCK_FILE); // creates the lock with its content in one step, and only when there is none
        break;
      } catch (err) {
        if (err.code !== "EEXIST") {
          if (!["EPERM", "ENOTSUP", "EXDEV", "EMLINK", "EACCES"].includes(err.code)) throw err;
          try { fs.copyFileSync(tmp, LOCK_FILE, fs.constants.COPYFILE_EXCL); break; } catch (e) { if (e.code !== "EEXIST") throw e; } // a file system without hard links
        }
      }
      const held = readLock();
      if (held === null) continue; // it went away meanwhile: try again
      if (!staleLock(held)) {
        console.error(`Another replacement of the local data is running (npm run dev:${held.kind || "load"}, pid ${held.pid}, started ${new Date(held.at).toLocaleString()}). Wait until it has finished, then run this again.\nNothing was changed. If no such command is running, delete ${rel(LOCK_FILE)}.`);
        process.exit(1);
      }
      // A dead run's lock: take it over. It is moved away first, so two processes cannot both think they removed it.
      const moved = `${LOCK_FILE}.stale-${process.pid}`;
      try { fs.renameSync(LOCK_FILE, moved); } catch { continue; }
      let taken = null;
      try { taken = JSON.parse(fs.readFileSync(moved, "utf8")); } catch { /* damaged */ }
      if (taken && Number.isInteger(taken.pid) && !staleLock(taken)) {
        try { fs.linkSync(moved, LOCK_FILE); } catch { /* somebody else holds the lock already */ }
        fs.rmSync(moved, { force: true });
        continue; // that was a live process's fresh lock, not the stale one: it has been put back
      }
      if (taken && taken.phase === "replacing" && taken.backup && fs.existsSync(taken.backup)) {
        const kept = keepBackup(taken.backup);
        console.error(`A previous npm run dev:${taken.kind} (pid ${taken.pid}) stopped halfway through replacing the local data. Its safety copy is kept at ${rel(kept)}; put it back with: npm run dev:load -- ${rel(kept)}`);
      }
      fs.rmSync(moved, { force: true });
    }
    if (readLock()?.pid !== process.pid) {
      console.error(`Could not take the lock ${rel(LOCK_FILE)}. Nothing was changed; run this again.`);
      process.exit(1);
    }
  } finally {
    fs.rmSync(tmp, { force: true });
  }
  process.on("exit", () => {
    if (run.phase === "replacing") afterWipeFailure(new Error("The command was interrupted"), { exiting: true });
    releaseLock();
  });
  for (const signal of ["SIGINT", "SIGTERM"]) process.on(signal, () => process.exit(130));
}

function setPhase(phase, backup) {
  run.phase = phase;
  if (backup !== undefined) run.backup = backup;
  if (readLock()?.pid !== process.pid) return;
  const tmp = writeLock({ phase, backup: run.backup });
  fs.renameSync(tmp, LOCK_FILE);
}

/** Everything the emulators hold, as a live-copy file's content: { docs, accounts, skipped }. */
export async function readEmulator() {
  const docs = [];
  const readCollection = async (collection) => {
    const refs = await collection.listDocuments(); // also documents that only hold subcollections
    for (let i = 0; i < refs.length; i += 100) {
      for (const snap of await db.getAll(...refs.slice(i, i + 100))) if (snap.exists) docs.push({ path: snap.ref.path, data: encode(snap.data()) });
    }
    for (const ref of refs) for (const sub of await ref.listCollections()) await readCollection(sub);
  };
  for (const collection of await db.listCollections()) await readCollection(collection);
  const accounts = [];
  let skipped = 0;
  if (auth) {
    let pageToken;
    do { // the same fields pull-live.mjs keeps from a live account; the sign-in picker needs no password
      const page = await auth.listUsers(1000, pageToken);
      for (const u of page.users) {
        if (!u.email) { skipped++; continue; }
        const google = u.providerData.find((p) => p.providerId !== "password") || u.providerData[0];
        accounts.push({
          uid: u.uid, email: u.email, displayName: u.displayName || null, photoURL: u.photoURL || null,
          provider: google ? google.providerId : "password", providerUid: google ? google.uid : undefined,
          emailVerified: u.emailVerified === true, disabled: u.disabled === true,
          ...(u.phoneNumber ? { phoneNumber: u.phoneNumber } : {}),
          ...(u.customClaims && Object.keys(u.customClaims).length ? { customClaims: u.customClaims } : {}),
        });
      }
      pageToken = page.pageToken;
    } while (pageToken);
  }
  return { docs, accounts, skipped };
}

/** Writes text to a file so that it is either all there or not at all (a temporary file, flushed, then renamed over). */
function writeAtomic(file, text, tmp = `${file}.tmp`) {
  const fd = fs.openSync(tmp, "w");
  try {
    fs.writeSync(fd, text);
    fs.fsyncSync(fd);
  } finally {
    fs.closeSync(fd);
  }
  fs.renameSync(tmp, file);
}

const BACKUP_FILE = (kind) => new RegExp(`^backup-before-${kind}-[0-9TZ-]+\\.json$`);

/** Saves what the emulators hold. Returns the file, or null when they hold nothing. Throws when it cannot be done (nothing is wiped then). */
async function makeBackup(kind) {
  const { docs, accounts, skipped } = await readEmulator();
  if (!docs.length && !accounts.length) return null;
  const now = new Date();
  const file = path.join(DATA_DIR, `backup-before-${kind}-${now.toISOString().replace(/[:.]/g, "-")}.json`);
  writeAtomic(file, JSON.stringify({ version: FORMAT, kind: "backup", project: PROJECT_ID, pulledAt: now.toISOString(), docs, accounts }), path.join(DATA_DIR, "backup-in-progress.tmp"));
  const back = JSON.parse(fs.readFileSync(file, "utf8")); // read it back: a safety copy that cannot be read is no safety
  if (back.docs.length !== docs.length || back.accounts.length !== accounts.length) throw new Error("the safety copy does not read back complete");
  console.log(`Safety copy of the current local data (${docs.length} documents, ${accounts.length} accounts${skipped ? `; ${skipped} accounts without an email address cannot be copied` : ""}): ${rel(file)}`);
  return file;
}

/** What to say when something fails AFTER the wipe: the local data is gone or half there, and the way back. */
export function afterWipeFailure(err, { exiting = false } = {}) {
  const back = run.backup && fs.existsSync(run.backup) ? keepBackup(run.backup) : null;
  run.phase = "failed";
  console.error(`\n${err && err.message ? err.message : err}`);
  if (back) {
    console.error(`The local emulator data was cleared and is INCOMPLETE. Your previous local data is saved in ${rel(back)}.\nPut it back with: npm run dev:load -- ${rel(back)}\nOr fill it again with: npm run dev:seed (the demo data) or npm run dev:load (the saved live copy).`);
  } else {
    console.error("The local emulator data was cleared and is INCOMPLETE. Fill it again with: npm run dev:seed (the demo data) or npm run dev:load (the saved live copy).");
  }
  if (!exiting) process.exit(1);
}

/**
 * Replaces the local data: docs [{ path, data }] and people (accounts). `source` is a file being loaded (never deleted as an old copy).
 * Returns { backup } (the safety copy's file or null). Exits the process on failure, after saying what happened and how to go back.
 */
export async function replaceLocalData(kind, { docs, people, source = null, backup = true }) {
  acquireLock(kind);
  let file = null;
  if (backup) {
    try {
      file = await makeBackup(kind);
    } catch (err) {
      console.error(`The current local data could not be saved first (${err && err.message ? err.message : err}). Nothing was changed. Free some disk space or fix the problem, or skip the safety copy with --no-backup.`);
      process.exit(1);
    }
  }
  setPhase("replacing", file);
  try {
    await wipe();
    await writeDocs(docs);
    await createAccounts(people);
  } catch (err) {
    afterWipeFailure(err);
  }
  setPhase("done");
  const kept = [];
  if (file) {
    for (const name of fs.readdirSync(DATA_DIR)) {
      const old = path.join(DATA_DIR, name);
      if (BACKUP_FILE(kind).test(name) && old !== file && (!source || path.resolve(source) !== old)) fs.rmSync(old, { force: true }); // only the newest copy of this kind stays
    }
  }
  for (const name of fs.readdirSync(DATA_DIR)) if (/^backup-before-.*\.failed\.json$/.test(name)) kept.push(rel(path.join(DATA_DIR, name)));
  if (file) console.log(`Previous local data stays in ${rel(file)} (npm run dev:load -- ${rel(file)} puts it back).`);
  if (kept.length) console.log(`Kept from a run that failed earlier: ${kept.join(", ")} (delete when you no longer need it).`);
  return { backup: file };
}

/** Writes [{ path: "apps/x/reviews/y", data }] in batches (Firestore allows 500 writes and about 10 MB per batch: 400 writes, 4 MB here). */
export async function writeDocs(docs) {
  let batch = db.batch();
  let count = 0;
  let bytes = 0;
  for (const { path: p, data } of docs) {
    let size = 0;
    try { size = JSON.stringify(data).length; } catch { /* values JSON cannot show (bigint) count as small */ }
    if (count && (count >= 400 || bytes + size > 4000000)) {
      await batch.commit();
      batch = db.batch();
      count = 0;
      bytes = 0;
    }
    batch.set(db.doc(p), data);
    count++;
    bytes += size;
  }
  if (count) await batch.commit();
}

/**
 * Local accounts, so the emulator's sign-in picker lists them: sign in as anyone with one click. A person is { email, displayName?,
 * uid?, photoURL?, provider? ("google.com" by default; "password" gives an email + password account with the password "password") }.
 * Keep a person's uid when the data refers to people by uid (a live copy does).
 */
export async function createAccounts(people) {
  if (!auth || !people.length) return;
  const users = people.map((p, i) => {
    const displayName = p.displayName || p.email.split("@")[0];
    const provider = p.provider || "google.com";
    return {
      uid: p.uid || `local-${i + 1}`,
      email: p.email,
      // A copy made by format 2 carries the real value; a seed person or a version-1 copy has none: true is what Google sets for its accounts (rules often check it).
      emailVerified: typeof p.emailVerified === "boolean" ? p.emailVerified : true,
      displayName,
      ...(p.photoURL ? { photoURL: p.photoURL } : {}),
      ...(p.phoneNumber ? { phoneNumber: p.phoneNumber } : {}),
      ...(p.disabled === true ? { disabled: true } : {}),
      ...(p.customClaims && typeof p.customClaims === "object" && Object.keys(p.customClaims).length ? { customClaims: p.customClaims } : {}),
      providerData: provider === "password" ? [] : [{ uid: p.providerUid || `${provider}-${p.email}`, email: p.email, displayName, providerId: provider }],
    };
  });
  for (let i = 0; i < users.length; i += 1000) {
    const result = await auth.importUsers(users.slice(i, i + 1000));
    if (result.failureCount) throw new Error(`Creating accounts failed: ${result.errors.map((e) => e.error.message).join("; ")}`);
  }
  for (const [i, p] of people.entries()) if (p.provider === "password") await auth.updateUser(users[i].uid, { password: "password" });
}

// ---- The live-copy file: Firestore values that JSON has no type for, tagged so they come back as the same type ----
//
// FORMAT 2 (the current one; the file says "version": 2): every special value is an object with exactly ONE reserved key "$sel":
//   { "$sel": "timestamp", seconds, nanoseconds }   { "$sel": "geopoint", latitude, longitude }   { "$sel": "ref", path }
//   { "$sel": "bytes", base64 }                     { "$sel": "number", value: "NaN" | "Infinity" | "-Infinity" }
//   { "$sel": "map", value: { ...entries encoded } }  an ordinary map that itself has a "$sel" key
// Any other map is written as it is (a map with a "__type" key needs no escaping). The decoder is strict: an unknown tag or a missing
// field throws, and load.mjs decodes everything before it wipes, so nothing is changed. A file without "version" is FORMAT 1 (a "__type"
// tag, no escaping), which still loads as it always did (decodeV1). pull-live.mjs repeats encode() (keep them in step).
export const FORMAT = 2;

export function encode(value) {
  if (value instanceof Timestamp) return { $sel: "timestamp", seconds: value.seconds, nanoseconds: value.nanoseconds };
  if (value instanceof GeoPoint) return { $sel: "geopoint", latitude: value.latitude, longitude: value.longitude };
  if (value && typeof value === "object" && typeof value.path === "string" && typeof value.listCollections === "function") return { $sel: "ref", path: value.path };
  if (Buffer.isBuffer(value) || value instanceof Uint8Array) return { $sel: "bytes", base64: Buffer.from(value).toString("base64") };
  if (typeof value === "number" && !Number.isFinite(value)) return { $sel: "number", value: String(value) };
  if (Array.isArray(value)) return value.map(encode);
  if (value && typeof value === "object") {
    const entries = Object.fromEntries(Object.entries(value).map(([k, v]) => [k, encode(v)]));
    return Object.prototype.hasOwnProperty.call(value, "$sel") ? { $sel: "map", value: entries } : entries;
  }
  return value;
}

const TAG_FIELDS = {
  timestamp: ["seconds", "nanoseconds"], geopoint: ["latitude", "longitude"], ref: ["path"], bytes: ["base64"], number: ["value"], map: ["value"],
};
const NUMBERS = { NaN: NaN, Infinity: Infinity, "-Infinity": -Infinity };

/** Format 2, strict. */
export function decode(value) {
  if (Array.isArray(value)) return value.map(decode);
  if (!value || typeof value !== "object") return value;
  if (!Object.prototype.hasOwnProperty.call(value, "$sel")) return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, decode(v)]));
  const tag = value.$sel;
  const fields = Object.prototype.hasOwnProperty.call(TAG_FIELDS, tag) ? TAG_FIELDS[tag] : null;
  if (!fields) throw new Error(`unknown value type "${String(tag)}"`);
  const keys = Object.keys(value).filter((k) => k !== "$sel").sort();
  if (keys.join() !== [...fields].sort().join()) throw new Error(`a "${tag}" value needs exactly ${fields.join(", ")} (it has ${keys.join(", ") || "nothing"})`);
  const int = (n) => Number.isInteger(n);
  const num = (n) => typeof n === "number" && Number.isFinite(n);
  switch (tag) {
    case "timestamp":
      if (!int(value.seconds) || !int(value.nanoseconds)) throw new Error("a timestamp needs whole numbers for seconds and nanoseconds");
      return new Timestamp(value.seconds, value.nanoseconds);
    case "geopoint":
      if (!num(value.latitude) || !num(value.longitude)) throw new Error("a geopoint needs numbers for latitude and longitude");
      return new GeoPoint(value.latitude, value.longitude);
    case "ref":
      if (typeof value.path !== "string" || !value.path) throw new Error("a reference needs a path");
      return db.doc(value.path);
    case "bytes":
      if (typeof value.base64 !== "string" || !/^[A-Za-z0-9+/]*={0,2}$/.test(value.base64)) throw new Error("bytes need a base64 text");
      return Buffer.from(value.base64, "base64");
    case "number":
      if (typeof value.value !== "string" || !Object.prototype.hasOwnProperty.call(NUMBERS, value.value)) throw new Error('a number tag is "NaN", "Infinity" or "-Infinity"');
      return NUMBERS[value.value];
    default: // map
      if (!value.value || typeof value.value !== "object" || Array.isArray(value.value)) throw new Error("a map needs an object as value");
      return Object.fromEntries(Object.entries(value.value).map(([k, v]) => [k, decode(v)]));
  }
}

/** Format 1 (copies made before "version" existed), exactly as it always decoded. */
export function decodeV1(value) {
  if (Array.isArray(value)) return value.map(decodeV1);
  if (value && typeof value === "object") {
    if (value.__type === "timestamp") return new Timestamp(value.seconds, value.nanoseconds);
    if (value.__type === "geopoint") return new GeoPoint(value.latitude, value.longitude);
    if (value.__type === "ref") return db.doc(value.path);
    if (value.__type === "bytes") return Buffer.from(value.base64, "base64");
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, decodeV1(v)]));
  }
  return value;
}

/** The decoder for a copy's "version" (missing = 1); throws for a version this script does not know. */
export function decoderFor(version) {
  if (version === undefined || version === 1) return decodeV1;
  if (version === FORMAT) return decode;
  throw new Error(`the copy has version ${JSON.stringify(version)}, which this script does not know (it reads 1 and ${FORMAT}); run: node scripts/sel-pull.mjs firebase`);
}
